-- evt:paybox
RegisterEvent(23, "Pay box", function(continueStep)
    if continueStep == 2 then
        XeenQuests.hook("dd18.pay_box")
        return
    end
    if continueStep ~= nil then
        evt.StatusText("Get lost!")
        return
    end
    if not (not (IsQBitSet(QBit(116120)))) then
        XeenQuests.hook("dd18.pay_box")
        return
    end
    evt.SetMessage("It costs 5,000 gold to use the gym. Pay?")
    evt.AskQuestion(23, 1, 0, 2, "Pay (Yes/No)?", {"Yes", "Y"})
end, "Pay box")

-- evt:protein_brew
RegisterEvent(24, "Protein Brew", function()
    if not XeenQuests.hook("dd18.members_room") then
        return
    end
    evt.ForPlayer(Players.Current)
    if IsPlayerBitSet(PlayerBit(11319)) then
        XeenQuests.hook("dd18.brew_again")
        return
    end
    AddValue(BaseMight, 2)
    SetPlayerBit(PlayerBit(11319))
    XeenQuests.hook("dd18.protein_brew")
end, "Protein Brew")

